"""QQ-卡面：富媒体结果卡片输出节点。

接收 IMAGE / VIDEO / AUDIO / media_bundle，把媒体落到 ComfyUI temp 并产出 ui，
前端卡面据此渲染：图像（缩放/批次）、视频（内联播放）、音频（音乐图标+进度条+动态频谱）。
生成中的实时预览与进度由前端挂 WebSocket 预览帧/progress 事件驱动，后端只负责最终结果。
"""

from __future__ import annotations

import os
import uuid
from collections.abc import Mapping
from typing import Any

import torch

from .utilities import WslAnyType


def _temp_name(ext: str) -> tuple[str, str]:
    import folder_paths
    directory = folder_paths.get_temp_directory()
    os.makedirs(directory, exist_ok=True)
    name = f"qq_card_{uuid.uuid4().hex[:10]}.{ext}"
    return directory, name


def _image_ui(images: torch.Tensor, prompt: Any, extra_pnginfo: Any) -> list[dict[str, Any]]:
    import nodes
    preview = nodes.PreviewImage()
    result = preview.save_images(images, filename_prefix="qq_card", prompt=prompt, extra_pnginfo=extra_pnginfo)
    return list((result or {}).get("ui", {}).get("images", []))


def _video_ui(video: Any) -> list[dict[str, Any]]:
    from comfy_api.latest import Types
    directory, name = _temp_name("mp4")
    video.save_to(os.path.join(directory, name), format=Types.VideoContainer("mp4"), codec="auto")
    return [{"filename": name, "subfolder": "", "type": "temp"}]


def _audio_ui(audio: Mapping[str, Any]) -> list[dict[str, Any]]:
    waveform = audio.get("waveform")
    if not isinstance(waveform, torch.Tensor):
        raise ValueError("音频必须包含 waveform 张量")
    sample_rate = int(audio.get("sample_rate") or 48_000)
    if waveform.ndim == 3:
        waveform = waveform[0]
    wav = waveform.detach().to(device="cpu", dtype=torch.float32)
    directory, name = _temp_name("wav")
    path = os.path.join(directory, name)
    try:
        import torchaudio
        torchaudio.save(path, wav, sample_rate)
    except Exception:
        import wave
        import numpy as np
        data = np.clip(wav.numpy().T, -1.0, 1.0)
        pcm = (data * 32767).astype(np.int16)
        channels = pcm.shape[1] if pcm.ndim > 1 else 1
        with wave.open(path, "wb") as handle:
            handle.setnchannels(channels)
            handle.setsampwidth(2)
            handle.setframerate(sample_rate)
            handle.writeframes(pcm.tobytes())
    return [{"filename": name, "subfolder": "", "type": "temp"}]


def _is_video(value: Any) -> bool:
    return hasattr(value, "get_components") and hasattr(value, "save_to")


def _is_audio(value: Any) -> bool:
    return isinstance(value, Mapping) and isinstance(value.get("waveform"), torch.Tensor)


def _bundle_entries(media_bundle: Any) -> list[tuple[str, Any]]:
    """把 media_bundle 拆成 (kind, value) 列表；复用 media 的拆分逻辑。"""
    try:
        from .media import _bundle_items
        entries = []
        for item in _bundle_items(media_bundle):
            kind = getattr(item, "kind", None) or getattr(item, "media_type", None)
            value = getattr(item, "value", None)
            if kind and value is not None:
                entries.append((str(kind), value))
        if entries:
            return entries
    except Exception:
        pass
    return []


def build_card_ui(media: Any, prompt: Any = None, extra_pnginfo: Any = None) -> dict[str, Any]:
    """按媒体类型产出 ui.images / ui.videos / ui.audio。空输入返回空 ui。"""
    ui: dict[str, Any] = {"images": [], "videos": [], "audio": []}
    if media is None:
        return ui

    entries: list[tuple[str, Any]]
    if isinstance(media, torch.Tensor):
        entries = [("image", media)]
    elif _is_video(media):
        entries = [("video", media)]
    elif _is_audio(media):
        entries = [("audio", media)]
    else:
        entries = _bundle_entries(media)
        if not entries:
            return ui

    for kind, value in entries:
        if kind == "image" and isinstance(value, torch.Tensor):
            ui["images"].extend(_image_ui(value, prompt, extra_pnginfo))
        elif kind == "video" and _is_video(value):
            ui["videos"].extend(_video_ui(value))
        elif kind == "audio" and _is_audio(value):
            ui["audio"].extend(_audio_ui(value))
    return ui


class QQCardPreview:
    CATEGORY = "QQ/工具"
    FUNCTION = "show"
    RETURN_TYPES = ()
    OUTPUT_NODE = True
    DESCRIPTION = (
        "富媒体结果卡面：接图像/视频/音频或 media_bundle，生成时在卡面实时预览，完成后呈现最终结果。"
        "图像可缩放/翻批次，视频内联播放，音频显示音乐图标+进度条+动态频谱。多个卡面节点可摆成卡面墙。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "标题": ("STRING", {"default": "卡面", "multiline": False}),
            },
            "optional": {
                "媒体": (WslAnyType, {"forceInput": True}),
            },
            "hidden": {"prompt": "PROMPT", "extra_pnginfo": "EXTRA_PNGINFO"},
        }

    @staticmethod
    def show(标题="卡面", 媒体=None, prompt=None, extra_pnginfo=None):
        return {"ui": build_card_ui(媒体, prompt, extra_pnginfo)}


NODE_CLASS_MAPPINGS = {"QQCardPreview": QQCardPreview}
NODE_DISPLAY_NAME_MAPPINGS = {"QQCardPreview": "QQ-卡面"}
